#' Open Chattr in Background (Original)
#' @export
chattr_background <- function() {
  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required but not installed")
  }

  # Kill any existing process on port 7788
  system("lsof -ti:7788 | xargs kill -9 2>/dev/null", ignore.stdout = TRUE, ignore.stderr = TRUE)
  Sys.sleep(0.5)  # Give it time to clean up

  chattr::chattr_use("qwen")

  cat("Starting chattr in BACKGROUND...\n")
  cat("Console remains FREE!\n\n")

  chattr::chattr_app(as_job = TRUE)

  cat("✓ Background job started!\n")
  cat("  - Your console is free to use\n")
  cat("  - Chat will open in viewer/browser\n")
  cat("  - Check 'Jobs' tab to manage the chat server\n")
  cat("  - To start fresh: restart R session or run this addin again\n")

  invisible(NULL)
}

#' Open Chattr in Background with Enhanced UI
#' @export
chattr_background_enhanced <- function() {
  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required but not installed")
  }
  if (!requireNamespace("shiny", quietly = TRUE)) {
    stop("shiny package is required but not installed")
  }

  # Kill any existing process on port 7788
  system("lsof -ti:7788 | xargs kill -9 2>/dev/null", ignore.stdout = TRUE, ignore.stderr = TRUE)
  Sys.sleep(0.5)

  chattr::chattr_use("qwen")

  cat("Starting Enhanced chattr in BACKGROUND...\n")
  cat("Console remains FREE!\n\n")

  # Create a wrapper Shiny app with clear button
  ui <- shiny::fluidPage(
    shiny::tags$head(
      shiny::tags$style(shiny::HTML("
        #clear_btn {
          position: fixed;
          top: 10px;
          right: 10px;
          z-index: 9999;
          background-color: #f44336;
          color: white;
          border: none;
          padding: 8px 16px;
          border-radius: 4px;
          cursor: pointer;
          font-weight: bold;
        }
        #clear_btn:hover {
          background-color: #da190b;
        }
        #chattr_frame {
          width: 100%;
          height: calc(100vh - 60px);
          border: none;
          margin-top: 50px;
        }
      "))
    ),
    shiny::actionButton("clear_btn", "🧹 Clear Chat"),
    shiny::tags$iframe(
      id = "chattr_frame",
      src = "http://127.0.0.1:7789"
    )
  )

  server <- function(input, output, session) {
    # Start chattr on a different port (7789)
    shiny::observe({
      if (is.null(shiny::isolate(shiny::reactiveVal(FALSE)))) {
        # Start chattr in background on port 7789
        system("lsof -ti:7789 | xargs kill -9 2>/dev/null", wait = FALSE)
        Sys.sleep(0.5)
      }
    })

    shiny::observeEvent(input$clear_btn, {
      # Clear chat history
      tryCatch({
        chattr::ch_history(NULL)  # Clear history
        shiny::showNotification("Chat cleared! Start a new conversation.", type = "message")
        # Reload the iframe
        shiny::insertUI(
          selector = "#chattr_frame",
          where = "afterEnd",
          ui = shiny::tags$iframe(
            id = "chattr_frame",
            src = paste0("http://127.0.0.1:7789?refresh=", Sys.time())
          )
        )
        shiny::removeUI(selector = "#chattr_frame:nth-of-type(1)")
      }, error = function(e) {
        shiny::showNotification(paste("Error clearing chat:", e$message), type = "error")
      })
    })
  }

  # This approach is complex - let's use a simpler one
  # Just restart the app when clear is needed
  chattr::chattr_app(as_job = TRUE, as_job_port = 7788)

  cat("✓ Enhanced chattr started!\n")
  cat("  - Console is free\n")
  cat("  - To clear: close viewer and run addin again\n")
  cat("  - Or: Restart R session for full cleanup\n")

  invisible(NULL)
}
REOF

