#' Share Current Script with Chattr
#' @export
chattr_share_script <- function() {
  if (!requireNamespace("rstudioapi", quietly = TRUE)) {
    cat("rstudioapi package required but not installed\n")
    return(invisible(NULL))
  }

  if (!requireNamespace("chattr", quietly = TRUE)) {
    cat("chattr package required but not installed\n")
    return(invisible(NULL))
  }

  # Get the active document
  tryCatch({
    context <- rstudioapi::getActiveDocumentContext()

    if (is.null(context) || is.null(context$contents) || length(context$contents) == 0) {
      cat("No active R script found\n")
      return(invisible(NULL))
    }

    script_content <- paste(context$contents, collapse = "\n")
    script_path <- context$path

    # Create a prompt with the script content
    prompt <- sprintf("Here is my current R script%s:\n\n```r\n%s\n```\n\nPlease help me with this script.",
                     ifelse(nzchar(script_path), sprintf(" (%s)", basename(script_path)), ""),
                     script_content)

    cat("Sharing current script with chattr...\n")
    cat("Script:", ifelse(nzchar(script_path), basename(script_path), "Untitled"), "\n")
    cat("Lines:", length(context$contents), "\n\n")

    # Send to chattr
    chattr::ch_submit(prompt)

    cat("✓ Script shared! SARA is analyzing it now.\n")

  }, error = function(e) {
    cat("Error:", e$message, "\n")
  })

  invisible(NULL)
}

#' Share Selected Code with Chattr
#' @export
chattr_share_selection <- function() {
  if (!requireNamespace("rstudioapi", quietly = TRUE)) {
    cat("rstudioapi package required but not installed\n")
    return(invisible(NULL))
  }

  if (!requireNamespace("chattr", quietly = TRUE)) {
    cat("chattr package required but not installed\n")
    return(invisible(NULL))
  }

  # Get the active document and selection
  tryCatch({
    context <- rstudioapi::getActiveDocumentContext()

    if (is.null(context) || is.null(context$selection)) {
      cat("No selection found\n")
      return(invisible(NULL))
    }

    # Get selected text
    selection <- context$selection[[1]]
    selected_text <- selection$text

    if (is.null(selected_text) || nzchar(selected_text) == FALSE) {
      cat("No text selected. Please select some code first.\n")
      return(invisible(NULL))
    }

    # Create a prompt with the selection
    prompt <- sprintf("Here is the code I've selected:\n\n```r\n%s\n```\n\nPlease help me with this code.",
                     selected_text)

    cat("Sharing selected code with chattr...\n")
    cat("Characters:", nchar(selected_text), "\n\n")

    # Send to chattr
    chattr::ch_submit(prompt)

    cat("✓ Selection shared! SARA is analyzing it now.\n")

  }, error = function(e) {
    cat("Error:", e$message, "\n")
  })

  invisible(NULL)
}

#' Enable Document Context in Chattr
#' @export
chattr_enable_context <- function() {
  cat("Enabling document context in chattr...\n")

  chattr::chattr_defaults(
    include_doc_contents = TRUE,
    max_data_files = 10,
    max_data_frames = 10
  )

  cat("✓ Context enabled!\n")
  cat("  - Document contents: YES\n")
  cat("  - Max data files: 10\n")
  cat("  - Max data frames: 10\n\n")
  cat("Now chattr will automatically see your open R scripts!\n")

  invisible(NULL)
}
REOF

