#' Share Dataframes with Chattr
#' Lists available dataframes and their structure
#' @param df_names Optional vector of dataframe names to share. If NULL, shows all.
#' @export
chattr_share_data <- function(df_names = NULL) {
  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required")
  }

  # Get all dataframes in global environment
  env_objects <- ls(envir = .GlobalEnv)
  dataframes <- env_objects[sapply(env_objects, function(x) {
    is.data.frame(get(x, envir = .GlobalEnv))
  })]

  if (length(dataframes) == 0) {
    cat("No dataframes found in your environment.\n")
    return(invisible(NULL))
  }

  # Filter to requested dataframes if specified
  if (!is.null(df_names)) {
    dataframes <- intersect(dataframes, df_names)
    if (length(dataframes) == 0) {
      cat("None of the specified dataframes found.\n")
      return(invisible(NULL))
    }
  }

  # Build context message
  context_parts <- list()
  context_parts[[1]] <- "Here are the dataframes in my R environment:\n"

  for (df_name in dataframes) {
    df <- get(df_name, envir = .GlobalEnv)

    # Get structure info
    str_output <- capture.output(str(df, max.level = 1))

    # Get preview (first few rows)
    preview <- capture.output(print(head(df, 3)))

    context_parts[[length(context_parts) + 1]] <- sprintf(
      "\n## %s\n\nStructure:\n%s\n\nPreview:\n%s\n",
      df_name,
      paste(str_output, collapse = "\n"),
      paste(preview, collapse = "\n")
    )
  }

  full_context <- paste(context_parts, collapse = "\n")

  cat("Sharing", length(dataframes), "dataframe(s) with SARA...\n")
  cat("Dataframes:", paste(dataframes, collapse = ", "), "\n\n")

  # Submit to chattr
  chattr::ch_submit(full_context)

  cat("✓ Dataframes shared!\n")
  invisible(dataframes)
}

#' Share Active Script with Chattr
#' @export
chattr_share_script <- function() {
  if (!requireNamespace("rstudioapi", quietly = TRUE)) {
    cat("rstudioapi package required for script sharing\n")
    return(invisible(NULL))
  }

  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required")
  }

  # Check if running in RStudio
  if (!rstudioapi::isAvailable()) {
    cat("This function requires RStudio\n")
    return(invisible(NULL))
  }

  # Get active document
  tryCatch({
    context <- rstudioapi::getActiveDocumentContext()

    if (is.null(context) || is.null(context$contents) || length(context$contents) == 0) {
      cat("No active R script found\n")
      return(invisible(NULL))
    }

    script_content <- paste(context$contents, collapse = "\n")
    script_path <- context$path
    script_name <- ifelse(nzchar(script_path), basename(script_path), "Untitled")

    # Build context message
    full_context <- sprintf(
      "Here is my current R script (%s):\n\n```r\n%s\n```\n",
      script_name,
      script_content
    )

    cat("Sharing script with SARA...\n")
    cat("Script:", script_name, "\n")
    cat("Lines:", length(context$contents), "\n\n")

    # Submit to chattr
    chattr::ch_submit(full_context)

    cat("✓ Script shared!\n")

  }, error = function(e) {
    cat("Error:", e$message, "\n")
  })

  invisible(NULL)
}

#' Enhanced chattr prompt processor with slash commands
#' @param message The message to send to chattr
#' @export
chattr_send <- function(message = NULL) {
  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required")
  }

  if (is.null(message) || !nzchar(message)) {
    cat("Usage: chattr_send('your message')\n")
    cat("Slash commands:\n")
    cat("  /data          - Share all dataframes\n")
    cat("  /data df1 df2  - Share specific dataframes\n")
    cat("  /script        - Share active R script\n")
    cat("\nExample: chattr_send('/data testdata /script Can you analyze this?')\n")
    return(invisible(NULL))
  }

  # Check for slash commands
  has_data <- grepl("/data", message, fixed = TRUE)
  has_script <- grepl("/script", message, fixed = TRUE)

  context_parts <- list()

  # Process /data command
  if (has_data) {
    # Extract dataframe names if specified
    data_match <- regmatches(message, regexpr("/data\\s+([a-zA-Z0-9_]+(?:\\s+[a-zA-Z0-9_]+)*)", message))

    if (length(data_match) > 0) {
      # Specific dataframes requested
      df_names <- strsplit(gsub("/data\\s+", "", data_match), "\\s+")[[1]]
      cat("Gathering dataframes:", paste(df_names, collapse = ", "), "\n")
    } else {
      # All dataframes
      df_names <- NULL
      cat("Gathering all dataframes...\n")
    }

    # Get dataframes context
    env_objects <- ls(envir = .GlobalEnv)
    dataframes <- env_objects[sapply(env_objects, function(x) {
      is.data.frame(get(x, envir = .GlobalEnv))
    })]

    if (!is.null(df_names)) {
      dataframes <- intersect(dataframes, df_names)
    }

    if (length(dataframes) > 0) {
      for (df_name in dataframes) {
        df <- get(df_name, envir = .GlobalEnv)
        str_output <- capture.output(str(df, max.level = 1))
        preview <- capture.output(print(head(df, 3)))

        context_parts[[length(context_parts) + 1]] <- sprintf(
          "\n## Dataframe: %s\n\n%s\n\nPreview:\n%s\n",
          df_name,
          paste(str_output, collapse = "\n"),
          paste(preview, collapse = "\n")
        )
      }
    }

    # Remove /data command from message
    message <- gsub("/data\\s+[a-zA-Z0-9_\\s]*", "", message)
    message <- gsub("/data", "", message, fixed = TRUE)
  }

  # Process /script command
  if (has_script) {
    if (requireNamespace("rstudioapi", quietly = TRUE) && rstudioapi::isAvailable()) {
      tryCatch({
        context <- rstudioapi::getActiveDocumentContext()

        if (!is.null(context) && !is.null(context$contents) && length(context$contents) > 0) {
          script_content <- paste(context$contents, collapse = "\n")
          script_path <- context$path
          script_name <- ifelse(nzchar(script_path), basename(script_path), "Untitled")

          context_parts[[length(context_parts) + 1]] <- sprintf(
            "\n## Current R Script: %s\n\n```r\n%s\n```\n",
            script_name,
            script_content
          )

          cat("Including script:", script_name, "\n")
        }
      }, error = function(e) {
        cat("Note: Could not get active script\n")
      })
    }

    # Remove /script command from message
    message <- gsub("/script", "", message, fixed = TRUE)
  }

  # Clean up message
  message <- trimws(message)

  # Build final message
  if (length(context_parts) > 0) {
    full_message <- paste(
      paste(context_parts, collapse = "\n"),
      "\n---\n\n",
      message,
      sep = ""
    )
  } else {
    full_message <- message
  }

  cat("\nSending to SARA...\n\n")

  # Submit to chattr
  chattr::ch_submit(full_message)

  cat("✓ Message sent!\n")
  invisible(NULL)
}
REOF

