# Context Bridge: Allows background chattr to access main session context
# This file provides functions that SARA can call to retrieve context

#' Get current context cache file path for this user
#' @keywords internal
get_context_cache_path <- function() {
  user <- Sys.info()["user"]
  cache_dir <- file.path(tempdir(), "chattr_context")
  if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
  file.path(cache_dir, paste0(user, "_context.rds"))
}

#' Retrieve all dataframes from user's environment
#' This function is called BY SARA when she needs to see dataframes
#' @export
get_user_dataframes <- function() {
  cache_file <- get_context_cache_path()

  if (!file.exists(cache_file)) {
    return("No dataframes available. User needs to update context cache.")
  }

  context <- tryCatch(
    readRDS(cache_file),
    error = function(e) NULL
  )

  if (is.null(context) || is.null(context$dataframes)) {
    return("No dataframes cached. User needs to run: chattrBackground::update_context()")
  }

  # Return formatted dataframe information
  df_info <- context$dataframes

  if (length(df_info) == 0) {
    return("No dataframes found in user's environment.")
  }

  # Build readable output
  output <- "Available dataframes:\n\n"
  for (df_name in names(df_info)) {
    df_data <- df_info[[df_name]]
    output <- paste0(output, "## ", df_name, "\n")
    output <- paste0(output, "Dimensions: ", df_data$dims[1], " rows x ", df_data$dims[2], " columns\n")
    output <- paste0(output, "Structure:\n", df_data$structure, "\n")
    output <- paste0(output, "Preview:\n", df_data$preview, "\n\n")
  }

  return(output)
}

#' Retrieve current active script content
#' This function is called BY SARA when she needs to see the script
#' @export
get_user_script <- function() {
  cache_file <- get_context_cache_path()

  if (!file.exists(cache_file)) {
    return("No script available. User needs to update context cache.")
  }

  context <- tryCatch(
    readRDS(cache_file),
    error = function(e) NULL
  )

  if (is.null(context) || is.null(context$script)) {
    return("No script cached. User needs to run: chattrBackground::update_context()")
  }

  script_info <- context$script

  if (script_info$content == "") {
    return("No active R script found.")
  }

  output <- sprintf(
    "Current R script: %s\n\n```r\n%s\n```",
    script_info$name,
    script_info$content
  )

  return(output)
}

#' Get all context (dataframes + script)
#' @export
get_user_context <- function() {
  df_context <- get_user_dataframes()
  script_context <- get_user_script()

  return(paste0(
    "=== USER CONTEXT ===\n\n",
    df_context, "\n\n",
    script_context
  ))
}
REOF

cat "Context bridge created at: /usr/local/lib/R/site-library/chattr_context_bridge.R"

