#' Update context cache for background SARA session
#' This allows SARA to automatically retrieve your dataframes and script
#' @param auto_refresh If TRUE, sets up automatic refresh every 30 seconds
#' @export
update_context <- function(auto_refresh = FALSE) {
  user <- Sys.info()["user"]
  cache_dir <- file.path(tempdir(), "chattr_context")
  if (!dir.exists(cache_dir)) dir.create(cache_dir, recursive = TRUE)
  cache_file <- file.path(cache_dir, paste0(user, "_context.rds"))

  context <- list()

  # Capture dataframes
  env_objects <- ls(envir = .GlobalEnv)
  dataframes <- env_objects[sapply(env_objects, function(x) {
    is.data.frame(get(x, envir = .GlobalEnv))
  })]

  df_info <- list()
  if (length(dataframes) > 0) {
    for (df_name in dataframes) {
      df <- get(df_name, envir = .GlobalEnv)

      str_output <- capture.output(str(df, max.level = 1))
      preview <- capture.output(print(head(df, 3)))

      df_info[[df_name]] <- list(
        dims = dim(df),
        structure = paste(str_output, collapse = "\n"),
        preview = paste(preview, collapse = "\n")
      )
    }
  }
  context$dataframes <- df_info

  # Capture active script
  script_info <- list(name = "", content = "")
  if (requireNamespace("rstudioapi", quietly = TRUE) && rstudioapi::isAvailable()) {
    tryCatch({
      doc_context <- rstudioapi::getActiveDocumentContext()
      if (!is.null(doc_context) && !is.null(doc_context$contents) && length(doc_context$contents) > 0) {
        script_info$name <- ifelse(nzchar(doc_context$path), basename(doc_context$path), "Untitled")
        script_info$content <- paste(doc_context$contents, collapse = "\n")
      }
    }, error = function(e) {
      # Silent fail if no active document
    })
  }
  context$script <- script_info
  context$updated_at <- Sys.time()

  # Save to cache
  saveRDS(context, cache_file)

  cat("✓ Context cache updated!\n")
  cat("  Dataframes:", length(df_info), "\n")
  cat("  Script:", ifelse(nzchar(script_info$name), script_info$name, "None"), "\n")
  cat("  Cache file:", cache_file, "\n")

  if (auto_refresh) {
    cat("\nSetting up auto-refresh (every 30 seconds)...\n")
    cat("Stop with: Ctrl+C or restart R session\n")

    while(TRUE) {
      Sys.sleep(30)
      update_context(auto_refresh = FALSE)
    }
  }

  invisible(cache_file)
}

#' Start auto-updating context in background
#' @export
start_context_sync <- function() {
  if (!requireNamespace("later", quietly = TRUE)) {
    cat("Installing 'later' package for background sync...\n")
    install.packages("later", repos = "https://cloud.r-project.org")
  }

  library(later)

  # Update immediately
  update_context()

  # Set up recurring update every 30 seconds
  later::later(function() {
    update_context()
    start_context_sync()  # Reschedule
  }, delay = 30)

  cat("\n✓ Context auto-sync started!\n")
  cat("  Updates every 30 seconds\n")
  cat("  SARA can now automatically see your dataframes and script\n")

  invisible(NULL)
}
REOF

echo "Context update functions added"

