#' Get user-specific port for chattr
#' @keywords internal
get_user_port <- function() {
  user <- Sys.info()["user"]
  hash_val <- sum(as.integer(charToRaw(user))) %% 100
  port <- 7700 + hash_val
  return(port)
}

#' Get context to inject into chat startup
#' @keywords internal
get_startup_context <- function() {
  user <- Sys.info()["user"]
  cache_dir <- file.path(tempdir(), "chattr_context")
  cache_file <- file.path(cache_dir, paste0(user, "_context.rds"))

  if (!file.exists(cache_file)) {
    return("")
  }

  context <- tryCatch(readRDS(cache_file), error = function(e) NULL)
  if (is.null(context)) return("")

  parts <- c("\n\n=== AUTOMATIC CONTEXT ===\n")

  # Add dataframes
  if (!is.null(context$dataframes) && length(context$dataframes) > 0) {
    parts <- c(parts, "\nUSER'S DATAFRAMES:\n")
    for (df_name in names(context$dataframes)) {
      df_data <- context$dataframes[[df_name]]
      parts <- c(parts, sprintf(
        "\n## %s (%d rows x %d cols)\n%s\n\nPreview:\n%s\n",
        df_name,
        df_data$dims[1],
        df_data$dims[2],
        df_data$structure,
        df_data$preview
      ))
    }
  }

  # Add script
  if (!is.null(context$script) && nzchar(context$script$content)) {
    parts <- c(parts, sprintf(
      "\nUSER'S ACTIVE SCRIPT: %s\n\n```r\n%s\n```\n",
      context$script$name,
      context$script$content
    ))
  }

  if (length(parts) == 1) {
    return("\n\n(No context available. User should run: chattrBackground::update_context())")
  }

  return(paste(parts, collapse = ""))
}

#' Open Chattr in Background with auto-context injection
#' @export
chattr_background <- function() {
  if (!requireNamespace("chattr", quietly = TRUE)) {
    stop("chattr package is required but not installed")
  }

  user_port <- get_user_port()
  user <- Sys.info()["user"]

  cat("Checking for existing chattr processes for user:", user, "\n")
  system(sprintf("lsof -ti:%d | xargs kill -9 2>/dev/null", user_port), 
         ignore.stdout = TRUE, ignore.stderr = TRUE)
  Sys.sleep(0.5)

  chattr::chattr_use("qwen")

  # Get and inject startup context
  startup_context <- get_startup_context()

  cat("\nStarting chattr in BACKGROUND...\n")
  cat("Console remains FREE!\n")
  cat("Your port:", user_port, "(user-specific)\n")

  if (nzchar(startup_context) && !grepl("No context available", startup_context)) {
    cat("✓ Context loaded and will be shared with SARA\n")
  } else {
    cat("⚠ No context cached. Run update_context() to share data/scripts with SARA\n")
  }
  cat("\n")

  # Start chattr with context injection
  # Note: We'll inject context via initial prompt
  chattr::chattr_app(
    as_job = TRUE,
    as_job_port = user_port,
    as_job_host = "127.0.0.1",
    viewer = "viewer"
  )

  # If context exists, automatically submit it
  if (nzchar(startup_context) && !grepl("No context available", startup_context)) {
    Sys.sleep(2)  # Wait for app to start
    tryCatch({
      chattr::ch_submit(startup_context)
    }, error = function(e) {
      cat("Note: Could not auto-inject context. Use 'Share Dataframes/Script' addins.\n")
    })
  }

  cat("✓ Background job started!\n")
  cat("  - Your console is free to use\n")
  cat("  - Chat is in the Viewer pane\n")
  cat("  - Your port:", user_port, "(isolated from other users)\n")
  cat("  - Use 'Clear Chat' addin to start fresh\n")
  cat("  - Use 'Update Context' addin to refresh data/script\n")

  invisible(user_port)
}

#' Clear Chattr History and Reload
#' @export
chattr_clear <- function() {
  user_port <- get_user_port()
  user <- Sys.info()["user"]

  cat("Clearing chat history for user:", user, "\n")

  tryCatch({
    chattr::ch_history(NULL)
    cat("✓ History cleared!\n")
  }, error = function(e) {
    cat("Note: Could not clear history:", e$message, "\n")
  })

  cat("\nRestarting chattr on your port:", user_port, "\n")
  system(sprintf("lsof -ti:%d | xargs kill -9 2>/dev/null", user_port), 
         ignore.stdout = TRUE, ignore.stderr = TRUE)
  Sys.sleep(0.5)

  chattr_background()

  invisible(NULL)
}

#' Stop Chattr Background Job
#' @export
chattr_stop <- function() {
  user_port <- get_user_port()
  user <- Sys.info()["user"]

  cat("Stopping chattr background job for user:", user, "\n")
  cat("Port:", user_port, "\n")
  system(sprintf("lsof -ti:%d | xargs kill -9 2>/dev/null", user_port), 
         ignore.stdout = TRUE, ignore.stderr = TRUE)
  cat("✓ Stopped!\n")
  invisible(NULL)
}
REOF

