# SARA Shiny App - Test Version
# Direct Ollama API integration with context sharing

library(shiny)
library(httr2)
library(jsonlite)

# System prompt for SARA
SYSTEM_PROMPT <- "Use the 'Tidy Modeling with R' (https://www.tmwr.org/) book as main reference
Use the 'R for Data Science' (https://r4ds.had.co.nz/) book as main reference
Use tidyverse packages: readr, ggplot2, dplyr, tidyr
For models, use tidymodels packages: recipes, parsnip, yardstick, workflows, broom
Avoid explanations unless requested by user, expecting code only

You are a helpful coding assistant that uses R and the tidyverse"

# Get user-specific port
get_user_port <- function() {
  user <- Sys.info()["user"]
  hash_val <- sum(as.integer(charToRaw(user))) %% 100
  return(7700 + hash_val)
}

# Get dataframes context
get_dataframes_context <- function() {
