    parts <- c(parts, sprintf("\n## %s\n%s\nPreview:\n%s\n", 
                              df_name, 
                              paste(str_output, collapse = "\n"),
                              paste(preview, collapse = "\n")))
  }
  return(paste(parts, collapse = "\n"))
}

# Get script context
get_script_context <- function() {
  if (!requireNamespace("rstudioapi", quietly = TRUE)) {
    return("RStudio API not available")
  }
  if (!rstudioapi::isAvailable()) {
    return("Not running in RStudio")
  }

