    script_name <- ifelse(nzchar(context$path), basename(context$path), "Untitled")
    script_content <- paste(context$contents, collapse = "\n")
    return(sprintf("Current R script (%s):\n\n```r\n%s\n```", script_name, script_content))
  }, error = function(e) {
    return(paste("Error getting script:", e$message))
  })
}

# Call Ollama API
call_ollama <- function(messages, model = "sara") {
  response <- request("http://127.0.0.1:11434/api/chat") %>%
    req_body_json(list(
      model = model,
      messages = messages,
      stream = FALSE
    )) %>%
    req_perform()

  content <- resp_body_json(response)
  return(content$message$content)
}

