                     class = "btn-primary btn-block"),
        br(), br(),
        actionButton("share_script", "📄 Share Script", 
                     class = "btn-primary btn-block"),
        br(), br(),
        actionButton("clear_chat", "🧹 Clear Chat", 
                     class = "btn-warning btn-block")
      ),
      hr(),
      p("Test Version - Direct Ollama API"),
      p(paste("Port:", get_user_port())),
      p(paste("User:", Sys.info()["user"]))
    ),

    mainPanel(
      div(class = "chat-container", 
          uiOutput("chat_history")
      ),
      fluidRow(
        column(10,
          textAreaInput("user_input", NULL, "", 
                       width = "100%", rows = 3,
                       placeholder = "Type your message to SARA...")
        ),
        column(2,
          br(),
          actionButton("send", "Send", 
                      class = "btn-success btn-block")
        )
      )
    )
  )
)

# Server
server <- function(input, output, session) {
  # Chat history reactive value
  chat_history <- reactiveVal(list(
    list(role = "system", content = SYSTEM_PROMPT)
  ))

  # Display chat history
  output$chat_history <- renderUI({
    messages <- chat_history()
    # Skip system message in display
    display_messages <- messages[sapply(messages, function(m) m$role != "system")]

    if (length(display_messages) == 0) {
      return(p("No messages yet. Start chatting with SARA!"))
    }

    lapply(display_messages, function(msg) {
      if (msg$role == "user") {
        div(class = "message user-message",
            strong("You: "), msg$content)
      } else {
        div(class = "message assistant-message",
            strong("SARA: "), msg$content)
      }
    })
  })

  # Send message
  observeEvent(input$send, {
    req(input$user_input)
    if (nchar(trimws(input$user_input)) == 0) return()

    user_msg <- input$user_input
    updateTextAreaInput(session, "user_input", value = "")

    # Add user message to history
    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = user_msg
    )
    chat_history(current_history)

    # Call Ollama
    showNotification("SARA is thinking...", type = "message", duration = 1)

    tryCatch({
      response <- call_ollama(current_history)

      # Add assistant response
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
        content = response
      )
      chat_history(current_history)

    }, error = function(e) {
      showNotification(paste("Error:", e$message), type = "error")
    })
  })

  # Share dataframes
  observeEvent(input$share_data, {
    context <- get_dataframes_context()

    # Add to chat as user message
    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = context
    )
    chat_history(current_history)

    showNotification("Dataframes shared with SARA", type = "message")
  })

  # Share script
  observeEvent(input$share_script, {
    context <- get_script_context()

    # Add to chat as user message
    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = context
    )
    chat_history(current_history)

    showNotification("Script shared with SARA", type = "message")
  })

  # Clear chat
  observeEvent(input$clear_chat, {
    chat_history(list(
      list(role = "system", content = SYSTEM_PROMPT)
    ))
    showNotification("Chat cleared", type = "warning")
  })
}

# Run app
shinyApp(ui = ui, server = server)
REOF

