library(shiny)
library(httr2)
library(jsonlite)

# Get user-specific port (same logic as chattrBackground)
get_user_port <- function() {
  user <- Sys.info()["user"]
  hash_val <- sum(as.integer(charToRaw(user))) %% 100
  port <- 7700 + hash_val
  return(port)
}

# Get SARA system prompt
get_system_prompt <- function() {
  base_prompt <- "Use the 'Tidy Modeling with R' (https://www.tmwr.org/) book as main reference
Use the 'R for Data Science' (https://r4ds.had.co.nz/) book as main reference
Use tidyverse packages: readr, ggplot2, dplyr, tidyr
For models, use tidymodels packages: recipes, parsnip, yardstick, workflows, broom
Avoid explanations unless requested by user, expecting code only

You are a helpful coding assistant that uses R and the tidyverse

CONTEXT SHARING:
Users can share their dataframes and scripts with you by clicking the context buttons.
When users share context, it will appear in the conversation.

If a user asks about data or code you haven't seen, kindly guide them to use the context sharing buttons."

  return(base_prompt)
}

# Get dataframes context (adapted from context_sharing.R)
get_dataframes_context <- function() {
  env_objects <- ls(envir = .GlobalEnv)
  dataframes <- env_objects[sapply(env_objects, function(x) {
    is.data.frame(get(x, envir = .GlobalEnv))
  })]

  if (length(dataframes) == 0) {
    return("No dataframes found in your environment.")
  }

  context_parts <- list()
  context_parts[[1]] <- "Here are the dataframes in my R environment:\n"

  for (df_name in dataframes) {
    df <- get(df_name, envir = .GlobalEnv)

    str_output <- capture.output(str(df, max.level = 1))
    preview <- capture.output(print(head(df, 3)))

    context_parts[[length(context_parts) + 1]] <- sprintf(
      "\n## %s\n\nStructure:\n%s\n\nPreview:\n%s\n",
      df_name,
      paste(str_output, collapse = "\n"),
      paste(preview, collapse = "\n")
    )
  }

  return(paste(context_parts, collapse = "\n"))
}

# Get script context (adapted from context_sharing.R)
get_script_context <- function() {
  if (!requireNamespace("rstudioapi", quietly = TRUE)) {
    return("rstudioapi package required for script sharing")
  }

  if (!rstudioapi::isAvailable()) {
    return("This function requires RStudio")
  }

  tryCatch({
    context <- rstudioapi::getActiveDocumentContext()

    if (is.null(context) || is.null(context$contents) || length(context$contents) == 0) {
      return("No active R script found")
    }

    script_content <- paste(context$contents, collapse = "\n")
    script_path <- context$path
    script_name <- ifelse(nzchar(script_path), basename(script_path), "Untitled")

    result <- sprintf(
      "Here is my current R script (%s):\n\n```r\n%s\n```\n",
      script_name,
      script_content
    )

    return(result)

  }, error = function(e) {
    return(paste("Error:", e$message))
  })
}

# Call Ollama API
call_ollama <- function(messages) {
  tryCatch({
    response <- request("http://127.0.0.1:11434/api/chat") |>
      req_body_json(list(
        model = "sara",
        messages = messages,
        stream = FALSE
      )) |>
      req_perform() |>
      resp_body_json()

    return(response$message$content)

  }, error = function(e) {
    return(paste("Error calling Ollama:", e$message))
  })
}

# UI
ui <- fluidPage(
  titlePanel("SARA Chat (Test - Direct Ollama)"),

  fluidRow(
    column(12,
      p(style = "color: #666;",
        paste0("User: ", Sys.info()["user"], " | Port: ", get_user_port()))
    )
  ),

  fluidRow(
    column(12,
      actionButton("share_data", "📊 Share Dataframes", class = "btn-primary"),
      actionButton("share_script", "📄 Share Script", class = "btn-primary"),
      actionButton("clear_chat", "🗑️ Clear Chat", class = "btn-warning"),
      hr()
    )
  ),

  fluidRow(
    column(12,
      div(
        id = "chat_container",
        style = "height: 400px; overflow-y: scroll; border: 1px solid #ddd; padding: 10px; background: #f9f9f9;",
        uiOutput("chat_history")
      )
    )
  ),

