#!/usr/bin/env python3
"""
Chat API Server for Qwen 2.5 14B via Ollama
Provides a simple HTTP API for the web frontend.
Includes function calling for SHARE paper search.

Run with: python /opt/qwen/chat_api.py
"""

from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
from typing import Optional
import ollama
import json
import asyncio
import subprocess
import psutil
import httpx

app = FastAPI(title="Qwen Chat API", version="1.0.0")

# Paper Search API configuration
PAPER_SEARCH_API = "http://127.0.0.1:8000"
PAPER_SEARCH_API_KEY = "TQ17-qj2GLaoYjT5Q4WXO4qpeNkSPo9RqjWiRkLVE_Q"

# Tool definition for Qwen function calling
SEARCH_PAPERS_TOOL = {
    "type": "function",
    "function": {
        "name": "search_papers",
        "description": "Search for academic papers in the SHARE research database. Use this tool when the user asks about research topics, studies, scientific findings, or wants to find relevant academic papers. The database contains papers from the Survey of Health, Ageing and Retirement in Europe (SHARE) and related research on aging, health, economics, and social sciences.",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "The search query describing the research topic or question. Be specific and use relevant academic terms."
                },
                "num_results": {
                    "type": "integer",
                    "description": "Number of papers to return (1-50). Default is 30. The results are ranked by relevance score (0-1, higher is better). Focus on papers with scores above 0.5 for your answer.",
                    "default": 30
                },
                "filters": {
                    "type": "object",
                    "description": "Optional metadata filters to narrow search results. IMPORTANT: Use {\"typeof\": \"questionnaire\"} when searching for SHARE questionnaires, variables, or instruments. Use {\"typeof\": \"methodology\"} when searching for SHARE methodology, sampling, or data collection procedures."
                }
            },
            "required": ["query"]
        }
    }
}

GET_PAPER_TOOL = {
    "type": "function",
    "function": {
        "name": "get_paper",
        "description": "Retrieve the FULL TEXT of a specific paper by its title. Use this tool AFTER searching when you need more detailed information from a specific paper - for example, to understand methodology details, find specific statistics, or get complete context. The full paper text can be very long (10,000+ characters).",
        "parameters": {
            "type": "object",
            "properties": {
                "title": {
                    "type": "string",
                    "description": "The title of the paper to retrieve (exact or partial match). Use the title from the search results."
                },
                "authors": {
                    "type": "string",
                    "description": "Optional: Authors of the paper (for disambiguation if multiple papers have similar titles)"
                }
            },
            "required": ["title"]
        }
    }
}

AVAILABLE_TOOLS = [SEARCH_PAPERS_TOOL, GET_PAPER_TOOL]


def search_papers(query: str, num_results: int = 30, filters: Optional[dict] = None) -> dict:
    """Call the paper search REST API."""
    try:
        with httpx.Client(timeout=60.0) as client:
            params = {"q": query, "top_k": min(num_results, 50)}
            if filters:
                params["filters"] = json.dumps(filters)
            response = client.get(
                f"{PAPER_SEARCH_API}/search",
                params=params,
                headers={"X-API-Key": PAPER_SEARCH_API_KEY}
            )
            response.raise_for_status()
            data = response.json()

            # Format results for the LLM - provide more context per paper
            results = []
            for r in data.get("results", []):
                meta = r.get("metadata", {})
                text = r.get("text", "")
                # Provide up to 1000 chars of excerpt for better context
                excerpt = text[:1000] + "..." if len(text) > 1000 else text
                results.append({
                    "title": meta.get("title", "Unknown"),
                    "authors": meta.get("authors", "Unknown"),
                    "citation": meta.get("citation", ""),
                    "relevance_score": round(r.get("score", 0), 3),
                    "excerpt": excerpt
                })

            return {
                "success": True,
                "query": query,
                "total_results": len(results),
                "papers": results
            }
    except httpx.HTTPStatusError as e:
        return {"success": False, "error": f"API error: {e.response.status_code}"}
    except Exception as e:
        return {"success": False, "error": str(e)}


def get_paper(title: str, authors: str = None) -> dict:
    """Retrieve full paper text from the database."""
    try:
        with httpx.Client(timeout=60.0) as client:
            params = {"title": title}
            if authors:
                params["authors"] = authors

            response = client.get(
                f"{PAPER_SEARCH_API}/paper",
                params=params,
                headers={"X-API-Key": PAPER_SEARCH_API_KEY}
            )
            response.raise_for_status()
            data = response.json()

            # Return paper info with full text
            # Truncate very long papers to fit in context
            full_text = data.get("full_text", "")
            max_chars = 50000  # ~12k tokens, reasonable for Qwen's 32k context
            if len(full_text) > max_chars:
                full_text = full_text[:max_chars] + f"\n\n[... truncated, {len(data.get('full_text', ''))} total characters ...]"

            return {
                "success": True,
                "title": data.get("title", ""),
                "authors": data.get("authors", ""),
                "year": data.get("year", ""),
                "citation": data.get("citation", ""),
                "abstract": data.get("abstract", ""),
                "full_text": full_text,
                "char_count": data.get("char_count", len(full_text))
            }
    except httpx.HTTPStatusError as e:
        if e.response.status_code == 404:
            return {"success": False, "error": f"Paper not found: {title}"}
        return {"success": False, "error": f"API error: {e.response.status_code}"}
    except Exception as e:
        return {"success": False, "error": str(e)}


def execute_tool_call(tool_name: str, arguments: dict) -> str:
    """Execute a tool call and return the result as a string."""
    if tool_name == "search_papers":
        result = search_papers(
            query=arguments.get("query", ""),
            num_results=arguments.get("num_results", 30),
            filters=arguments.get("filters")
        )
        return json.dumps(result, indent=2, ensure_ascii=False)
    elif tool_name == "get_paper":
        result = get_paper(
            title=arguments.get("title", ""),
            authors=arguments.get("authors")
        )
        return json.dumps(result, indent=2, ensure_ascii=False)
    else:
        return json.dumps({"error": f"Unknown tool: {tool_name}"}, ensure_ascii=False)


def process_share_command(message: str) -> tuple[str, bool]:
    """
    Check if message contains /SHARE or /Summarize command and extract query.
    Returns (processed_message, should_force_tool).

    Usage examples:
    - "/SHARE cognitive decline" -> forces search for "cognitive decline"
    - "/Summarize SHARE Wave 8 Sampling" -> forces get_paper for that title
    - "Tell me about aging" -> no forced tool, let Qwen decide
    """
    import re

    # Pattern: /SHARE or /share followed by the query
    share_pattern = r'^/[Ss][Hh][Aa][Rr][Ee]\s+(.+)$'
    share_match = re.match(share_pattern, message.strip())

    if share_match:
        query = share_match.group(1).strip()
        # Transform to a direct instruction to search
        return f"Search for academic papers about: {query}. Use the search_papers tool.", True

    # Pattern: /Summarize or /summarize followed by paper title
    summarize_pattern = r'^/[Ss][Uu][Mm][Mm][Aa][Rr][Ii][Zz][Ee]\s+(.+)$'
    summarize_match = re.match(summarize_pattern, message.strip())

    if summarize_match:
        title = summarize_match.group(1).strip()
        # Transform to a direct instruction to get the paper
        return f"Retrieve and summarize the full text of the paper titled: {title}. Use the get_paper tool.", True

    return message, False

# CORS for web frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["https://search.share-r.at", "http://localhost:*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

MODEL = "sara"
CONTEXT_WINDOW = 32768


class ChatMessage(BaseModel):
    role: str
    content: str


class ChatRequest(BaseModel):
    messages: list[ChatMessage]
    stream: Optional[bool] = True
    system_prompt: Optional[str] = None
    enable_tools: Optional[bool] = True  # Enable paper search by default


class ChatResponse(BaseModel):
    message: ChatMessage
    tokens_used: Optional[int] = None


@app.get("/health")
async def health():
    """Health check endpoint."""
    try:
        models = ollama.list()
        model_loaded = any(m.model == MODEL for m in models.models)
        return {
            "status": "ok",
            "model": MODEL,
            "model_loaded": model_loaded,
            "context_window": CONTEXT_WINDOW
        }
    except Exception as e:
        return {"status": "error", "detail": str(e)}


@app.post("/chat")
async def chat(request: ChatRequest):
    """Chat endpoint with streaming support and optional tool calling."""

    # Build messages list - system prompt is baked into the model via Modelfile
    messages = []
    if request.system_prompt:
        # Only add system message if custom prompt provided (overrides Modelfile)
        messages.append({"role": "system", "content": request.system_prompt})

    # Process messages and check for /SHARE command
    force_search = False
    for msg in request.messages:
        content = msg.content
        if msg.role == "user":
            content, force_search = process_share_command(content)
        messages.append({"role": msg.role, "content": content})

    # Determine if tools should be used
    tools = AVAILABLE_TOOLS if request.enable_tools else None

    if request.stream:
        return StreamingResponse(
            stream_response(messages, tools),
            media_type="text/event-stream"
        )
    else:
        # Non-streaming response with tool support
        try:
            response = ollama.chat(model=MODEL, messages=messages, tools=tools)

            # Handle tool calls
            if response.message.tool_calls:
                # Execute tool calls and continue conversation
                messages.append(response.message)

                for tool_call in response.message.tool_calls:
                    tool_result = execute_tool_call(
                        tool_call.function.name,
                        tool_call.function.arguments
                    )
                    messages.append({
                        "role": "tool",
                        "content": tool_result
                    })

                # Get final response after tool execution
                final_response = ollama.chat(model=MODEL, messages=messages, tools=tools)
                return ChatResponse(
                    message=ChatMessage(
                        role="assistant",
                        content=final_response.message.content
                    )
                )

            return ChatResponse(
                message=ChatMessage(
                    role="assistant",
                    content=response.message.content
                )
            )
        except Exception as e:
            raise HTTPException(status_code=500, detail=str(e))


async def stream_response(messages: list, tools: list = None):
    """Generator for streaming chat responses with tool support."""
    try:
        # Send immediate thinking status so user sees activity
        yield f"data: {json.dumps({'content': '', 'type': 'thinking'}, ensure_ascii=False)}\n\n"


        # First call - may include tool calls (this is where the delay happens)
        response = ollama.chat(
            model=MODEL,
            messages=messages,
            tools=tools,
            stream=False  # Need non-streaming to check for tool calls
        )

        # Check if Qwen wants to use a tool
        if response.message.tool_calls:
            # Add assistant message with tool call to conversation
            messages.append(response.message)

            # Execute each tool call
            for tool_call in response.message.tool_calls:
                tool_name = tool_call.function.name

                # Notify user about the tool being used
                if tool_name == "search_papers":
                    yield f"data: {json.dumps({'content': '🔍 Searching papers...', 'type': 'status'}, ensure_ascii=False)}\n\n"
                elif tool_name == "get_paper":
                    yield f"data: {json.dumps({'content': '📄 Retrieving paper...', 'type': 'status'}, ensure_ascii=False)}\n\n"

                tool_result = execute_tool_call(
                    tool_name,
                    tool_call.function.arguments
                )
                messages.append({
                    "role": "tool",
                    "content": tool_result
                })

                # Send tool result notification
                try:
                    result_data = json.loads(tool_result)
                    if result_data.get("success"):
                        if tool_name == "search_papers":
                            count = result_data.get("total_results", 0)
                            status_msg = f"\n\nFound {count} relevant papers. Analyzing...\n\n"
                        elif tool_name == "get_paper":
                            title = result_data.get("title", "paper")[:50]
                            status_msg = f"\n\nRetrieved: {title}... Summarizing...\n\n"
                        else:
                            status_msg = ""
                        if status_msg:
                            yield f"data: {json.dumps({'content': status_msg, 'type': 'status'}, ensure_ascii=False)}\n\n"
                except:
                    pass

            # Now stream the final response
            stream = ollama.chat(
                model=MODEL,
                messages=messages,
                tools=tools,
                stream=True
            )

            for chunk in stream:
                content = chunk.message.content
                if content:
                    data = json.dumps({"content": content}, ensure_ascii=False)
                    yield f"data: {data}\n\n"
        else:
            # No tool calls - stream the direct response
            # Re-run with streaming since we got a non-streaming response
            stream = ollama.chat(
                model=MODEL,
                messages=messages,
                tools=tools,
                stream=True
            )

            for chunk in stream:
                content = chunk.message.content
                if content:
                    data = json.dumps({"content": content}, ensure_ascii=False)
                    yield f"data: {data}\n\n"

        yield "data: [DONE]\n\n"

    except Exception as e:
        error_data = json.dumps({"error": str(e)}, ensure_ascii=False)
        yield f"data: {error_data}\n\n"


@app.post("/clear")
async def clear_context():
    """Endpoint to signal context clear (handled client-side)."""
    return {"status": "ok", "message": "Context cleared"}


def get_gpu_stats():
    """Get GPU statistics via nvidia-smi."""
    try:
        result = subprocess.run(
            ['nvidia-smi', '--query-gpu=memory.used,memory.total,utilization.gpu,temperature.gpu',
             '--format=csv,noheader,nounits'],
            capture_output=True, text=True, timeout=5
        )
        if result.returncode == 0:
            parts = result.stdout.strip().split(', ')
            return {
                'gpu_mem_used_mb': int(parts[0]),
                'gpu_mem_total_mb': int(parts[1]),
                'gpu_utilization': int(parts[2]),
                'gpu_temp_c': int(parts[3])
            }
    except Exception:
        pass
    return None


@app.get("/stats")
async def get_stats():
    """Get system statistics including GPU utilization."""
    # CPU
    cpu_percent = psutil.cpu_percent(interval=0.1)

    # RAM
    mem = psutil.virtual_memory()

    # GPU
    gpu = get_gpu_stats()

    # Paper search API service status
    paper_search_active = is_service_active("paper-search-api.service")

    return {
        "cpu": {
            "usage_percent": cpu_percent
        },
        "ram": {
            "used_gb": round(mem.used / (1024**3), 1),
            "total_gb": round(mem.total / (1024**3), 1),
            "usage_percent": mem.percent
        },
        "gpu": gpu,
        "paper_search_active": paper_search_active
    }


def is_service_active(service_name: str) -> bool:
    """Check if a systemd service is active."""
    try:
        result = subprocess.run(
            ['systemctl', 'is-active', service_name],
            capture_output=True, text=True, timeout=5
        )
        return result.stdout.strip() == 'active'
    except Exception:
        return False


PAPER_SEARCH_SERVICES = ["paper-search-api.service", "paper-search-mcp.service"]


@app.post("/llamaindex/stop")
async def stop_llamaindex():
    """Stop LlamaIndex services to free GPU memory."""
    errors = []
    for service in PAPER_SEARCH_SERVICES:
        try:
            result = subprocess.run(
                ['systemctl', 'stop', service],
                capture_output=True, text=True, timeout=30
            )
            if result.returncode != 0:
                errors.append(f"{service}: {result.stderr.strip()}")
        except Exception as e:
            errors.append(f"{service}: {str(e)}")

    if errors:
        return {"status": "error", "errors": errors}
    return {"status": "ok", "message": "LlamaIndex services stopped"}


@app.post("/llamaindex/start")
async def start_llamaindex():
    """Start LlamaIndex services."""
    errors = []
    for service in PAPER_SEARCH_SERVICES:
        try:
            result = subprocess.run(
                ['systemctl', 'start', service],
                capture_output=True, text=True, timeout=30
            )
            if result.returncode != 0:
                errors.append(f"{service}: {result.stderr.strip()}")
        except Exception as e:
            errors.append(f"{service}: {str(e)}")

    if errors:
        return {"status": "error", "errors": errors}
    return {"status": "ok", "message": "LlamaIndex services started"}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8002)

