# ============================================================================
# SHINY SERVER
# ============================================================================

server <- function(input, output, session) {

  # Initialize chat history with system message
  chat_history <- reactiveVal(list(
    list(role = "system", content = get_system_prompt())
  ))

  # Render chat history (skip system message in display)
  output$chat_history <- renderUI({
    messages <- chat_history()

    if (length(messages) <= 1) {
      return(p(style = "color: #999;", "Start chatting with SARA... She can now search R help and retrieve your data/scripts automatically!"))
    }

    # Skip system message and tool messages in display
    display_messages <- messages[-1]
    display_messages <- Filter(function(msg) msg$role != "tool", display_messages)

    ui_messages <- lapply(display_messages, function(msg) {
      if (msg$role == "user") {
        div(
          style = "margin: 10px 0; padding: 10px; background: #e3f2fd; border-radius: 5px;",
          tags$strong("You:"),
          tags$pre(style = "margin: 5px 0; white-space: pre-wrap;", msg$content)
        )
      } else if (msg$role == "assistant") {
        # Show tool calls if present
        tool_info <- ""
        if (!is.null(msg$tool_calls)) {
          tool_names <- sapply(msg$tool_calls, function(tc) tc$`function`$name)
          tool_info <- tags$div(
            style = "color: #28a745; font-size: 0.9em; margin: 5px 0;",
            paste("🔧 Called:", paste(tool_names, collapse = ", "))
          )
        }

        div(
          style = "margin: 10px 0; padding: 10px; background: #fff; border: 1px solid #ddd; border-radius: 5px;",
          tags$strong("SARA:"),
          tool_info,
          tags$pre(style = "margin: 5px 0; white-space: pre-wrap;", msg$content)
        )
      }
    })

    tagList(ui_messages)
  })

  # Send message
  observeEvent(input$send, {
    req(input$user_input)
    user_msg <- input$user_input

    if (nchar(trimws(user_msg)) == 0) return()

    # Add user message
    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = user_msg
    )
    chat_history(current_history)

    updateTextInput(session, "user_input", value = "")

    showNotification("SARA is thinking (with tools)...", type = "message", duration = NULL, id = "thinking")

    # Call Ollama with tool support
    result <- call_ollama_with_tools(current_history, get_tools())

    # Update history with new messages (including tool calls)
    chat_history(result$messages)

    # Add final response
    if (!is.null(result$content) && nchar(result$content) > 0) {
      current_history <- chat_history()
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
        content = result$content
      )
      chat_history(current_history)
    }

    removeNotification(id = "thinking")
  })

  # Manual share dataframes (still available as button)
  observeEvent(input$share_data, {
    context <- get_user_dataframes()
    showNotification("Sharing dataframes with SARA...", type = "message")

    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = context
    )
    chat_history(current_history)

    showNotification("SARA is processing...", type = "message", duration = NULL, id = "thinking")

    result <- call_ollama_with_tools(current_history, get_tools())
    chat_history(result$messages)

    if (!is.null(result$content) && nchar(result$content) > 0) {
      current_history <- chat_history()
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
