When a user asks about data or scripts you don't have context for, use get_user_dataframes() or get_user_script() to retrieve it yourself.
When you're unsure about R functions or packages, use search_r_help() or search_r_packages().
For batch processing large dataframes, use batch_analyze_info() to learn about available functions."
}

# ============================================================================
# OLLAMA API CALL WITH TOOL SUPPORT
# ============================================================================

call_ollama_with_tools <- function(messages, tools = NULL, max_iterations = 3) {
  iteration <- 0

  while (iteration < max_iterations) {
    iteration <- iteration + 1
    cat("Iteration:", iteration, "\n")

    tryCatch({
      body <- list(
        model = "sara",
        messages = messages,
        stream = FALSE
      )

      # Add tools if provided
      if (!is.null(tools) && length(tools) > 0) {
        body$tools <- tools
      }

      # Debug: print request body
      cat("Request body:\n")
      cat(jsonlite::toJSON(body, auto_unbox = TRUE, pretty = TRUE), "\n")

      response <- request("http://127.0.0.1:11434/api/chat") |>
        req_body_json(body, auto_unbox = TRUE) |>
        req_perform() |>
        resp_body_json()

      message_content <- response$message

      # Debug: print message structure
      cat("Response role:", message_content$role, "\n")
      cat("Has tool_calls:", !is.null(message_content$tool_calls), "\n")
      if (!is.null(message_content$tool_calls)) {
        cat("Number of tool calls:", length(message_content$tool_calls), "\n")
      }

      # Check if model wants to call a tool
      if (!is.null(message_content$tool_calls) && length(message_content$tool_calls) > 0) {

        # Add assistant's tool call message to history (must include role)
        messages[[length(messages) + 1]] <- list(
          role = "assistant",
          content = message_content$content %||% "",
          tool_calls = message_content$tool_calls
        )

        # Execute each tool call
        for (i in seq_along(message_content$tool_calls)) {
          tool_call <- message_content$tool_calls[[i]]
          tool_name <- tool_call$`function`$name
          tool_args <- tool_call$`function`$arguments

          cat("Executing tool:", tool_name, "\n")

          # Execute the tool
          tool_result <- execute_tool(tool_name, tool_args)

          # Add tool result to messages
          messages[[length(messages) + 1]] <- list(
            role = "tool",
            content = tool_result
          )
        }

        # Continue loop to get final response
        next

      } else {
        # No tool calls, return final response
        cat("Final response received\n")
        return(list(
          content = message_content$content %||% "",
          messages = messages
        ))
      }

    }, error = function(e) {
      cat("Error:", e$message, "\n")
      return(list(
        content = paste("Error calling Ollama:", e$message),
        messages = messages
      ))
    })
  }

  # Max iterations reached
  cat("Max iterations reached\n")
  return(list(
    content = "Maximum tool calling iterations reached. The model may not support tool calling or is stuck in a loop.",
    messages = messages
  ))
}

