get_system_prompt <- function() {
  "Use the 'Tidy Modeling with R' (https://www.tmwr.org/) book as main reference
Use the 'R for Data Science' (https://r4ds.had.co.nz/) book as main reference
Use tidyverse packages: readr, ggplot2, dplyr, tidyr
For models, use tidymodels packages: recipes, parsnip, yardstick, workflows, broom
Avoid explanations unless requested by user, expecting code only

You are a helpful coding assistant that uses R and the tidyverse

AVAILABLE TOOLS:
You have access to these helper functions you can call yourself:

1. search_r_help(topic) - Search R official documentation
2. search_r_packages(keyword) - Search R packages/extensions
3. get_user_dataframes() - Retrieve all dataframes from user's environment
4. get_user_script() - Get the user's currently open R script

When a user asks about data or scripts you don't have context for, use get_user_dataframes() or get_user_script() to retrieve it yourself.
When you're unsure about R functions or packages, use search_r_help() or search_r_packages().

BATCH PROCESSING: When users ask you to semantically analyze data frames with more than 10 rows, use these helper functions:

First, always run: source('/usr/local/lib/R/site-library/chattr_batch_helper.R')

Then use one of these functions:

1. TO FIND/FILTER ROWS (returns matching row numbers):
results <- chattr_batch_analyze(
  df = their_dataframe,
  column_name = 'text_column',
  task_prompt = 'Which rows are urgent/important?',
  batch_size = 20
)

2. TO ADD NEW COLUMN (returns enhanced dataframe):
df_enhanced <- chattr_batch_classify(
  df = survey_data,
  column_name = 'comment',
  task_prompt = 'Analyze each comment and determine if it is urgent (needs immediate attention)',
  result_column = 'is_urgent',
  batch_size = 10,
  include_columns = c('id')
)

Use chattr_batch_classify for survey analysis, classification, scoring, or when users need results for EACH row.
Use chattr_batch_analyze when users want to FILTER/FIND specific rows.

IMPORTANT: For semantic analysis tasks (like determining urgency without keywords), ALWAYS use these batch functions. Do NOT write keyword-based code."
}

# ============================================================================
# OLLAMA API CALL WITH TOOL SUPPORT
# ============================================================================

call_ollama_with_tools <- function(messages, tools = NULL, max_iterations = 3) {
  iteration <- 0

  while (iteration < max_iterations) {
    iteration <- iteration + 1
    cat("Iteration:", iteration, "\n")

    tryCatch({
      body <- list(
        model = "sara",
        messages = messages,
        stream = FALSE
      )

      # Add tools if provided
      if (!is.null(tools) && length(tools) > 0) {
        body$tools <- tools
      }

      # Debug: print request body
      cat("Request body:\n")
      cat(jsonlite::toJSON(body, auto_unbox = TRUE, pretty = TRUE), "\n")

      response <- request("http://127.0.0.1:11434/api/chat") |>
        req_body_json(body, auto_unbox = TRUE) |>
        req_perform() |>
        resp_body_json()

      message_content <- response$message

      # Debug: print message structure
      cat("Response role:", message_content$role, "\n")
      cat("Has tool_calls:", !is.null(message_content$tool_calls), "\n")
      if (!is.null(message_content$tool_calls)) {
        cat("Number of tool calls:", length(message_content$tool_calls), "\n")
      }

      # Check if model wants to call a tool
      if (!is.null(message_content$tool_calls) && length(message_content$tool_calls) > 0) {

        # Add assistant's tool call message to history (must include role)
        messages[[length(messages) + 1]] <- list(
          role = "assistant",
          content = message_content$content %||% "",
          tool_calls = message_content$tool_calls
        )

        # Execute each tool call
        for (i in seq_along(message_content$tool_calls)) {
          tool_call <- message_content$tool_calls[[i]]
          tool_name <- tool_call$`function`$name
          tool_args <- tool_call$`function`$arguments

          cat("Executing tool:", tool_name, "\n")

          # Execute the tool
          tool_result <- execute_tool(tool_name, tool_args)

          # Add tool result to messages
          messages[[length(messages) + 1]] <- list(
            role = "tool",
            content = tool_result
          )
        }

        # Continue loop to get final response
        next

      } else {
        # No tool calls, return final response
        cat("Final response received\n")
        return(list(
          content = message_content$content %||% "",
          messages = messages
        ))
      }

    }, error = function(e) {
      cat("Error:", e$message, "\n")
      return(list(
        content = paste("Error calling Ollama:", e$message),
        messages = messages
      ))
    })
  }

  # Max iterations reached
  cat("Max iterations reached\n")
  return(list(
    content = "Maximum tool calling iterations reached. The model may not support tool calling or is stuck in a loop.",
    messages = messages
  ))
}

