      content = user_msg
    )
    chat_history(current_history)

    updateTextInput(session, "user_input", value = "")

    showNotification("SARA is thinking (with tools)...", type = "message", duration = NULL, id = "thinking")

    # Call Ollama with tool support
    result <- call_ollama_with_tools(current_history, get_tools())

    # Update history with new messages (including tool calls)
    chat_history(result$messages)

    # Add final response
    if (!is.null(result$content) && nchar(result$content) > 0) {
      current_history <- chat_history()
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
        content = result$content
      )
      chat_history(current_history)
    }

    removeNotification(id = "thinking")
  })

  # Manual share dataframes (still available as button)
  observeEvent(input$share_data, {
    context <- get_user_dataframes()
    showNotification("Sharing dataframes with SARA...", type = "message")

    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = context
    )
    chat_history(current_history)

    showNotification("SARA is processing...", type = "message", duration = NULL, id = "thinking")

    result <- call_ollama_with_tools(current_history, get_tools())
    chat_history(result$messages)

    if (!is.null(result$content) && nchar(result$content) > 0) {
      current_history <- chat_history()
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
        content = result$content
      )
      chat_history(current_history)
    }

    removeNotification(id = "thinking")
    showNotification("✓ Context shared!", type = "message", duration = 2)
  })

  # Manual share script (still available as button)
  observeEvent(input$share_script, {
    context <- get_user_script()
    showNotification("Sharing script with SARA...", type = "message")

    current_history <- chat_history()
    current_history[[length(current_history) + 1]] <- list(
      role = "user",
      content = context
    )
    chat_history(current_history)

    showNotification("SARA is processing...", type = "message", duration = NULL, id = "thinking")

    result <- call_ollama_with_tools(current_history, get_tools())
    chat_history(result$messages)

    if (!is.null(result$content) && nchar(result$content) > 0) {
      current_history <- chat_history()
      current_history[[length(current_history) + 1]] <- list(
        role = "assistant",
        content = result$content
      )
      chat_history(current_history)
    }

    removeNotification(id = "thinking")
    showNotification("✓ Script shared!", type = "message", duration = 2)
  })

  # Clear chat
  observeEvent(input$clear_chat, {
    chat_history(list(
      list(role = "system", content = get_system_prompt())
    ))
    showNotification("Chat cleared!", type = "message", duration = 2)
  })
}

